# ---------------------------------------------------------------------------
# Датчики давления
from typing import Dict
import random

# ---------------------------------------------------------------------------
# Sensorlarni quvurlar bo'yicha yaratish
# ---------------------------------------------------------------------------
def quvur_boyicha_sensorlar_yarat(pipes: Dict[str, Dict]) -> Dict[str, Dict]:
    sensorlar = {}
    sensor_index = 1

    for pipe_id, pipe in pipes.items():
        route = pipe.get("route", [])

        if len(route) < 2:
            continue

        nuqtalar = []
        nuqtalar.append(route[0])                 # boshlanish
        nuqtalar.append(route[len(route) // 2])   # o'rta
        nuqtalar.append(route[-1])                # oxiri

        for i, point in enumerate(nuqtalar, start=1):
            lat, lng = point

            sensor_id = f"S{sensor_index}"
            sensorlar[sensor_id] = {
                "id": sensor_id,
                "pipe_id": pipe_id,
                "lat": lat,
                "lng": lng,
                "baseline_pressure": round(random.uniform(6.0, 7.8), 1),
                "label": f"{pipe_id} sensori {i}",
            }
            sensor_index += 1

    return sensorlar


# ---------------------------------------------------------------------------
# Tasodifiy sizib chiqish
# ---------------------------------------------------------------------------
def tasodifiy_anomaliya_yarat(pipes: Dict[str, Dict], sensors: Dict[str, Dict]) -> Dict:
    if not pipes:
        return {}

    pipe_id = random.choice(list(pipes.keys()))

    shu_quvur_sensorlari = {
        sensor_id: sensor
        for sensor_id, sensor in sensors.items()
        if sensor.get("pipe_id") == pipe_id
    }

    affected_sensors = {}

    for sensor_id in shu_quvur_sensorlari:
        affected_sensors[sensor_id] = -round(random.uniform(0.5, 1.8), 1)

    severity = random.choice(["low", "medium", "high"])

    return {
        "name": f"{pipe_id} da tasodifiy sizib chiqish",
        "pipe_id": pipe_id,
        "affected_sensors": affected_sensors,
        "severity_hint": severity,
    }


# ---------------------------------------------------------------------------
# Avtomatik generatsiya
# ---------------------------------------------------------------------------
SENSORS: Dict[str, Dict] = quvur_boyicha_sensorlar_yarat(PIPES)

LEAK_SCENARIOS: Dict[str, Dict] = {
    "random_leak": tasodifiy_anomaliya_yarat(PIPES, SENSORS)
}
